    pixel.r = texture(tex, v_uv + offset * (1.0 - (N_R - 1.0) * factor)).r;
    pixel.g = texture(tex, v_uv + offset * (1.0 - (N_G - 1.0) * factor)).g;
    pixel.b = texture(tex, v_uv + offset * (1.0 - (N_B - 1.0) * factor)).b;
